INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 62, 1, "カリン", 0.0, -416.5, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 1, 1000001, "2030/01/01 14:59:59", 1, 3.414, 190801, "2025/01/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 62, 2, "カリン", 0.0, -416.5, "ミッションをクリアして、\n報酬をゲットしましょう！", 1, 1000002, "2030/01/01 14:59:59", 1, 3.099, 190801, "2025/01/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 63, 3, "カリン", 0.0, -416.5, "受け取ることができる\n報酬があるようです\n確認してみてください", 1, 1000003, "2030/01/01 14:59:59", 1, 2.801, 190801, "2025/01/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 63, 4, "カリン", 0.0, -416.5, "報酬がもらえますよ！\nチェックしてみてください", 1, 1000004, "2030/01/01 14:59:59", 2, 0.0, 190801, "2025/01/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 64, 5, "カリン", 0.0, -363.0, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 1, 1000005, "2030/01/01 14:59:59", 2, 2.12, 190801, "2025/01/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 64, 6, "カリン", 0.0, -363.0, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 1, 1000006, "2030/01/01 14:59:59", 1, 1.68, 190801, "2025/01/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 64, 7, "カリン", 0.0, -363.0, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 1, 1000007, "2030/01/01 14:59:59", 2, 2.33, 190801, "2025/01/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7, 61, 101, "ラビリスタ", -6.0, -285.0, "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", 10201, 1020101, "2030/01/01 14:59:59", 3, 5.18, 133701, "2025/01/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 61, 201, "クリスティーナ", -2.0, -285.0, "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", 10201, 1020102, "2030/01/01 14:59:59", 1, 8.77, 133901, "2025/01/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 61, 301, "ネネカ", 0.0, -285.0, "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", 10201, 1020103, "2030/01/01 14:59:59", 6, 15.5, 133801, "2025/01/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5, 61, 101, "ランファ", 0.0, -285.0, "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", 10202, 1020201, "2030/01/01 14:59:59", 2, 9.061, 134301, "2025/02/28 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 61, 201, "チカ", 0.0, -285.0, "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", 10202, 1020202, "2030/01/01 14:59:59", 1, 7.699, 134401, "2025/02/28 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 61, 101, "アオイ", 0.0, -285.0, "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", 10203, 1020301, "2030/01/01 14:59:59", 1, 8.595, 134601, "2025/03/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 61, 201, "クローチェ", 0.0, -285.0, "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", 10203, 1020302, "2030/01/01 14:59:59", 1, 7.758, 134501, "2025/03/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6, 61, 101, "ルイズマリー", 0.0, -285.0, "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", 10204, 1020401, "2030/01/01 14:59:59", 2, 7.0, 132302, "2025/04/30 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 61, 201, "イロハ", 0.0, -285.0, "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", 10204, 1020402, "2030/01/01 14:59:59", 1, 7.904, 132402, "2025/04/30 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 61, 301, "ソノ", 0.0, -285.0, "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", 10204, 1020403, "2030/01/01 14:59:59", 4, 8.487, 132502, "2025/04/30 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 61, 101, "カノン", 0.0, -285.0, "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", 10205, 1020502, "2030/01/01 14:59:59", 1, 8.763, 134901, "2025/05/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, 61, 201, "ツムギ", 0.0, -285.0, "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", 10205, 1020503, "2030/01/01 14:59:59", 1, 6.417, 134801, "2025/05/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7, 61, 101, "エリス", 0.0, -285.0, "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", 10206, 1020601, "2030/01/01 14:59:59", 3, 10.335, 135001, "2025/06/30 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (4, 61, 201, "シェフィ", 0.0, -285.0, "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", 10206, 1020602, "2030/01/01 14:59:59", 2, 6.281, 135101, "2025/06/30 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 61, 301, "プレシア", 0.0, -285.0, "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", 10206, 1020603, "2030/01/01 14:59:59", 1, 12.244, 135201, "2025/06/30 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (8, 61, 101, "クリア", 0.0, -285.0, "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", 10207, 1020701, "2030/01/01 14:59:59", 2, 6.339, 135301, "2025/07/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (9, 61, 201, "アネモネ", 0.0, -285.0, "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", 10207, 1020702, "2030/01/01 14:59:59", 7, 8.184, 135401, "2025/07/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 61, 101, "アイラ", 0.0, -285.0, "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", 10208, 1020801, "2030/01/01 14:59:59", 9, 3.906, 129101, "2025/08/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 61, 201, "シナツ", 0.0, -285.0, "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", 10208, 1020802, "2030/01/01 14:59:59", 1, 14.465, 129201, "2025/08/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, 61, 301, "ヒヨリ", 0.0, -285.0, "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", 10208, 1020803, "2030/01/01 14:59:59", 4, 8.662, 100101, "2025/08/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, 61, 401, "レイ", 0.0, -285.0, "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", 10208, 1020804, "2030/01/01 14:59:59", 1, 10.915, 100301, "2025/08/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7, 61, 101, "ユキノ", 0.0, -285.0, "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", 10209, 1020901, "2030/01/01 14:59:59", 1, 6.042, 135802, "2025/09/30 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 61, 201, "サツキ", 0.0, -285.0, "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", 10209, 1020902, "2030/01/01 14:59:59", 4, 9.402, 135903, "2025/09/30 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 61, 301, "ルルィ", 0.0, -285.0, "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", 10209, 1020903, "2030/01/01 14:59:59", 8, 8.16, 136902, "2025/09/30 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 61, 101, "カスミ", 0.0, -285.0, "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", 10210, 1021001, "2030/01/01 14:59:59", 3, 5.0, 137401, "2025/10/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 61, 201, "アラクネ", 0.0, -285.0, "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", 10210, 1021002, "2030/01/01 14:59:59", 4, 8.12, 136001, "2025/10/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 61, 301, "ナーナ", 0.0, -285.0, "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", 10210, 1021003, "2030/01/01 14:59:59", 4, 6.386, 136202, "2025/10/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (4, 61, 101, "ユイ", 0.0, -285.0, "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", 10211, 1021101, "2030/01/01 14:59:59", 3, 7.438, 136402, "2025/11/30 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5, 61, 201, "ミソラ", 0.0, -285.0, "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", 10211, 1021102, "2030/01/01 14:59:59", 1, 8.35, 136302, "2025/11/30 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 61, 101, "シズル", 0.0, -285.0, "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", 10212, 1021201, "2030/01/01 14:59:59", 1, 5.0, 136501, "2025/12/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 61, 201, "リノ", 0.0, -285.0, "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", 10212, 1021202, "2030/01/01 14:59:59", 1, 5.25, 137902, "2025/12/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 61, 301, "ラビリスタ", 0.0, -285.0, "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", 10212, 1021203, "2030/01/01 14:59:59", 1, 7.5, 106801, "2025/12/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 61, 101, "ライラエル", 0.0, -285.0, "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", 10213, 1021301, "2030/01/01 14:59:59", 1, 8.204, 126501, "2026/01/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 61, 201, "ネフィ＝ネラ", 0.0, -285.0, "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", 10213, 1021302, "2030/01/01 14:59:59", 1, 7.176, 129701, "2026/01/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5, 61, 301, "ヴァイオレット", 0.0, -285.0, "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", 10213, 1021303, "2030/01/01 14:59:59", 1, 8.602, 133101, "2026/01/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, 61, 102, "ライラエル", 0.0, -285.0, "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", 10213, 1021304, "2030/01/01 14:59:59", 1, 10.14, 138101, "2026/02/06 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7, 61, 202, "ネフィ＝ネラ", 0.0, -285.0, "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", 10213, 1021305, "2030/01/01 14:59:59", 1, 10.152, 138201, "2026/02/06 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, 61, 302, "ヴァイオレット", 0.0, -285.0, "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", 10213, 1021306, "2030/01/01 14:59:59", 4, 9.688, 138001, "2026/02/06 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 61, 401, "ペコリーヌ", 0.0, -285.0, "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", 10213, 1021307, "2030/01/01 14:59:59", 2, 5.928, 138301, "2026/02/12 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 61, 101, "ワカナ", 0.0, -285.0, "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", 10214, 1021401, "2030/01/01 14:59:59", 4, 9.19, 138702, "2026/02/28 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, 61, 201, "シオリ", 0.0, -285.0, "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", 10214, 1021402, "2030/01/01 14:59:59", 1, 8.724, 138802, "2026/02/28 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 61, 101, "グレイス", 0.0, -285.0, "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", 10215, 1021501, "2030/01/01 14:59:59", 4, 7.758, 138902, "2026/03/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (4, 61, 201, "キョウカ", 0.0, -285.0, "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", 10215, 1021502, "2030/01/01 14:59:59", 6, 6.375, 139002, "2026/03/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 61, 301, "ルルィ", 0.0, -285.0, "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", 10215, 1021503, "2030/01/01 14:59:59", 6, 6.173, 136902, "2026/03/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 61, 101, "ミホ", 0.0, -285.0, "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", 10216, 1021601, "2030/01/01 14:59:59", 6, 4.202, 139202, "2026/04/30 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 61, 201, "マホ", 0.0, -285.0, "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", 10216, 1021602, "2030/01/01 14:59:59", 6, 2.842, 139302, "2026/04/30 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 61, 301, "エリカ", 0.0, -285.0, "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", 10216, 1021603, "2030/01/01 14:59:59", 4, 4.598, 139402, "2026/04/30 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, 61, 101, "リリ", 0.0, -285.0, "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", 10217, 1021701, "2030/01/01 14:59:59", 4, 6.533, 125802, "2026/05/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, 61, 301, "プレシア", 0.0, -285.0, "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", 10217, 1021702, "2030/01/01 14:59:59", 3, 5.0, 126102, "2026/05/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (4, 61, 201, "クリア", 0.0, -285.0, "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", 10217, 1021703, "2030/01/01 14:59:59", 3, 5.214, 126002, "2026/05/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, 61, 102, "リリ", 0.0, -285.0, "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", 10217, 1021704, "2030/01/01 14:59:59", 1, 8.781, 139501, "2026/05/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 61, 202, "クリア", 0.0, -285.0, "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", 10217, 1021705, "2030/01/01 14:59:59", 2, 6.529, 139601, "2026/05/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 61, 302, "プレシア", 0.0, -285.0, "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", 10217, 1021706, "2030/01/01 14:59:59", 3, 3.195, 139701, "2026/05/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, 61, 101, "ルイズマリー", 0.0, -285.0, "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", 10218, 1021801, "2030/01/01 14:59:59", 2, 12.43, 139902, "2026/06/30 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, 61, 201, "クレジッタ", 0.0, -285.0, "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", 10218, 1021802, "2030/01/01 14:59:59", 2, 6.35, 140001, "2026/06/30 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5, 61, 101, "フブキ", 0.0, -285.0, "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", 10219, 1021901, "2030/01/01 14:59:59", 1, 10.23, 140102, "2026/07/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 61, 201, "ヴァンピィ", 0.0, -285.0, "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", 10219, 1021902, "2030/01/01 14:59:59", 1, 5.584, 140201, "2026/07/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, 61, 201, "クローチェ", 0.0, -285.0, "あっちもこっちも、\nエマージェンシーですっ！\nみんなのピンチを助けるために\n行きましょうっ、ナイトさんっ！", 10220, 1022001, "2030/01/01 14:59:59", 6, 2.8, 126401, "2026/08/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, 61, 101, "ヴルム", 0.0, -285.0, "みんながあたしを許してくれても…\nあたしは、あたしを許せない\nそれでも…この世界が危ないなら\n迷ってなんか、いられない", 10220, 1022002, "2030/01/01 14:59:59", 4, 8.9, 127802, "2026/08/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 61, 202, "クローチェ", 0.0, -285.0, "クローチェ、サブマリンモードっ\n換装完了ですっ♪\nどんな荒波も、ナイトさんとなら\n越えちゃいますからっ！", 10220, 1022003, "2030/01/01 14:59:59", 2, 4.49, 140602, "2026/08/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, 61, 102, "ヴルム", 0.0, -285.0, "偽物でも、創り物でもいい\nあたしの中にある気持ちは、\nあたしの本物だから\n今度こそ、この力で守ってみせる", 10220, 1022004, "2030/01/01 14:59:59", 1, 9.42, 140501, "2026/08/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 61, 301, "リーザ", 0.0, -285.0, "世界と向き合うなんてこと…\n私には、わからない\nそれでも、受けた借りは\nちゃんと返さないとね", 10220, 1022005, "2030/01/01 14:59:59", 4, 7.0, 140402, "2026/08/31 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 62, 1, "カリン", 0.0, -416.5, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 2, 2000001, "2030/01/01 14:59:59", 1, 3.414, 190805, "2026/04/10 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 62, 2, "カリン", 0.0, -416.5, "ミッションをクリアして、\n報酬をゲットしましょう！", 2, 2000002, "2030/01/01 14:59:59", 1, 3.099, 190805, "2026/04/10 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 63, 3, "カリン", 0.0, -416.5, "受け取ることができる\n報酬があるようです\n確認してみてください", 2, 2000003, "2030/01/01 14:59:59", 1, 2.801, 190805, "2026/04/10 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 63, 4, "カリン", 0.0, -416.5, "報酬がもらえますよ！\nチェックしてみてください", 2, 2000004, "2030/01/01 14:59:59", 2, 0.0, 190805, "2026/04/10 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 64, 5, "カリン", 0.0, -363.0, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 2, 2000005, "2030/01/01 14:59:59", 2, 2.12, 190805, "2026/04/10 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, 64, 6, "カリン", 0.0, -363.0, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 2, 2000006, "2030/01/01 14:59:59", 1, 1.68, 190805, "2026/04/10 12:00:00");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, 64, 7, "カリン", 0.0, -363.0, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 2, 2000007, "2030/01/01 14:59:59", 2, 2.33, 190805, "2026/04/10 12:00:00");
